package edgefleet

import (
	"bytes"
	"strings"
	"testing"
)

func runPartitionedSliding(t *testing.T, input string, window, slide, partitions int64) (string, string, error) {
	t.Helper()
	var stdout, stderr bytes.Buffer
	err := RunAggregatePartitionedSliding(strings.NewReader(input), window, slide, partitions, &stdout, &stderr)
	return stdout.String(), stderr.String(), err
}

// Sliding windows combine with partitions: the same key from different
// partitions merges within each overlapping window, and only the effective
// (minimum) watermark closes them.
func TestAggregatePartitionedSlidingMergesPerWindow(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
		`{"type":"watermark","time":5000,"partition":0}`, // ahead: effective still unknown
		`{"type":"watermark","time":1000,"partition":1}`, // min = 1000: closes only [0,1000)
		`{"type":"watermark","time":5000,"partition":0}`, // p0 repeats; min stays 1000
		`{"type":"watermark","time":1600,"partition":1}`, // min = 1600: closes [600,1600)
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("unexpected stderr: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		`{"key":"k","start":600,"end":1600,"count":2,"sum":5}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

// The late-event check uses the effective watermark: an event below the min
// is skipped entirely even while an overlapping window covering its time is
// still open.
func TestAggregatePartitionedSlidingLateUsesEffectiveWatermark(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"watermark","time":5000,"partition":0}`,
		`{"type":"watermark","time":1000,"partition":1}`,                // effective = 1000
		`{"type":"event","key":"k","time":999,"value":1,"partition":0}`, // late despite open [600,1600)
		`{"type":"event","key":"k","time":1000,"value":4,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":1}`,
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := `{"key":"k","start":600,"end":1600,"count":1,"sum":4}` + "\n"
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	wantErr := "line 3: late event time=999 below current watermark 1000, skipped\n"
	if stderr != wantErr {
		t.Fatalf("stderr = %q, want %q", stderr, wantErr)
	}
}

// Before the effective watermark exists nothing closes and nothing is late;
// an idle declaration can itself close overlapping windows.
func TestAggregatePartitionedSlidingIdleCloses(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"idle","partition":1}`, // effective = 1600: [0,1000) and [600,1600) close
	}, "\n")
	stdout, _, err := runPartitionedSliding(t, input, 1000, 600, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		`{"key":"k","start":600,"end":1600,"count":2,"sum":5}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

// Existing partition validation still applies with sliding windows.
func TestAggregatePartitionedSlidingInvalidPartitionAndArgs(t *testing.T) {
	bad := `{"type":"event","key":"k","time":700,"value":1,"partition":9}` + "\n"
	_, _, err := runPartitionedSliding(t, bad, 1000, 600, 2)
	if err == nil {
		t.Fatal("expected out-of-range partition error")
	}
	inputErr, ok := err.(*InputError)
	if !ok {
		t.Fatalf("expected *InputError, got %T: %v", err, err)
	}
	if !strings.Contains(inputErr.Reason, "[0,2)") {
		t.Fatalf("reason = %q, want partition range", inputErr.Reason)
	}

	for _, sl := range []int64{0, -1, 1001} {
		if err := RunAggregatePartitionedSliding(strings.NewReader(""), 1000, sl, 2, &bytes.Buffer{}, &bytes.Buffer{}); err == nil {
			t.Fatalf("expected error for slide %d", sl)
		}
	}
}

package edgefleet

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// AggregateResult is one closed window output line.
type AggregateResult struct {
	Key   string `json:"key"`
	Start int64  `json:"start"`
	End   int64  `json:"end"`
	Count int64  `json:"count"`
	Sum   int64  `json:"sum"`
}

// InputError reports a fatal problem with one physical input line.
type InputError struct {
	Line   int
	Reason string
}

func (e *InputError) Error() string {
	return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
}

// OutputError reports that output triggered by one physical input line could
// not be written in full. Line is that input line (blank lines count), and
// Kind is either "window result" or "late-event notice". Detail identifies
// the record: a window's key and [start,end), or the skipped event time and
// the watermark used to judge it. Err is the writer's own error, including
// when only a prefix was accepted before it failed; when the writer reported
// no error but accepted too few bytes, Err is io.ErrShortWrite. Use
// errors.Is to inspect it. Content the writer already accepted stays in
// place and fully written earlier results stay valid.
type OutputError struct {
	Line   int
	Kind   string
	Detail string
	Err    error
}

func (e *OutputError) Error() string {
	return fmt.Sprintf("line %d: %s not fully written (%s): %v", e.Line, e.Kind, e.Detail, e.Err)
}

func (e *OutputError) Unwrap() error {
	return e.Err
}

// writeFull writes all of p to w in one call. Any writer error is returned
// unchanged, even when the writer accepted a prefix first, so callers keep
// errors.Is access to the original error. A nil error with fewer than
// len(p) accepted bytes is reported as io.ErrShortWrite; writeFull never
// retries or resends the missing tail.
func writeFull(w io.Writer, p []byte) error {
	n, err := w.Write(p)
	if err != nil {
		return err
	}
	if n < len(p) {
		return io.ErrShortWrite
	}
	return nil
}

// AggregateParamName identifies which aggregate start parameter a
// *AggregateParamError reports.
type AggregateParamName string

const (
	// AggregateParamWindow is the window length (--window-ms).
	AggregateParamWindow AggregateParamName = "window"
	// AggregateParamSlide is the slide interval (--slide-ms).
	AggregateParamSlide AggregateParamName = "slide"
	// AggregateParamPartitions is the partition count (--partitions).
	AggregateParamPartitions AggregateParamName = "partitions"
)

// AggregateParamKind classifies the problem ValidateAggregateParams found with
// one parameter.
type AggregateParamKind string

const (
	// AggregateParamNotPositive means the value was zero or negative where a
	// positive signed 64-bit integer is required.
	AggregateParamNotPositive AggregateParamKind = "not_positive"
	// AggregateParamTooLarge means the slide interval exceeds the window
	// length. It is reported for AggregateParamSlide and carries the window
	// length in Limit.
	AggregateParamTooLarge AggregateParamKind = "too_large"
)

// AggregateParamError reports one invalid aggregate start parameter. It is the
// single source of the shared startup parameter limits: every aggregate entry
// point (the library runners and the command line) funnels its numeric
// parameter checks through ValidateAggregateParams, so the same restriction is
// stated in one place. Which parameter may be omitted, and what an omitted or
// zero value means, is entry-specific and decided by the caller; this reports
// only the limits common to every entry. Field identifies the parameter, Kind
// the violated limit, Value the rejected value and Limit the window length for
// AggregateParamTooLarge (zero otherwise). Error renders the library entry
// point's existing wording, which callers may rephrase for their own surface
// while keeping the field-driven decision identical.
type AggregateParamError struct {
	Field AggregateParamName
	Kind  AggregateParamKind
	Value int64
	Limit int64
}

func (e *AggregateParamError) Error() string {
	switch e.Kind {
	case AggregateParamTooLarge:
		return fmt.Sprintf("slide interval %d must not exceed window length %d", e.Value, e.Limit)
	case AggregateParamNotPositive:
		switch e.Field {
		case AggregateParamWindow:
			return fmt.Sprintf("window length must be a positive signed 64-bit integer, got %d", e.Value)
		case AggregateParamSlide:
			return fmt.Sprintf("slide interval must be a positive signed 64-bit integer, got %d", e.Value)
		case AggregateParamPartitions:
			return fmt.Sprintf("partition count must be a positive signed 64-bit integer, got %d", e.Value)
		}
	}
	return fmt.Sprintf("invalid aggregate parameter %s: %d", e.Field, e.Value)
}

// ValidateAggregateParams enforces the aggregate startup limits shared by every
// entry point, in the order they have always been reported: window length,
// then slide interval, then the slide-vs-window comparison, then the partition
// count. windowMillis must be a positive signed 64-bit integer. slideMillis
// must be a positive signed 64-bit integer no greater than windowMillis; it
// does not have to divide windowMillis, and equality is the fixed-window case.
// partitions must not be negative; zero itself is accepted here because the
// library entry points use it to select legacy single-watermark mode -- an
// entry that rejects an explicitly supplied zero (the command line) keeps that
// policy of its own before or around this call. The first violated limit is
// returned as *AggregateParamError; nil means the parameters are sound and the
// caller may start reading input, so no invalid configuration ever reaches the
// input reader.
func ValidateAggregateParams(windowMillis, slideMillis, partitions int64) error {
	if windowMillis <= 0 {
		return &AggregateParamError{Field: AggregateParamWindow, Kind: AggregateParamNotPositive, Value: windowMillis}
	}
	if slideMillis <= 0 {
		return &AggregateParamError{Field: AggregateParamSlide, Kind: AggregateParamNotPositive, Value: slideMillis}
	}
	if slideMillis > windowMillis {
		return &AggregateParamError{Field: AggregateParamSlide, Kind: AggregateParamTooLarge, Value: slideMillis, Limit: windowMillis}
	}
	if partitions < 0 {
		return &AggregateParamError{Field: AggregateParamPartitions, Kind: AggregateParamNotPositive, Value: partitions}
	}
	return nil
}

type windowID struct {
	start int64 // inclusive window start in milliseconds since time zero
	key   string
}

type windowState struct {
	end   int64 // exclusive window end in milliseconds
	count int64
	sum   int64
}

// RunAggregate reads line-delimited JSON records from r and writes closed
// fixed window results, one JSON object per line, to out. windowMillis must
// be a positive signed 64-bit integer. Windows are fixed-length, start at
// time zero and use a left-closed right-open interval. Closure is driven
// solely by input watermarks: a window whose end is less than or equal to the
// current watermark is emitted once, ordered by end ascending and then by key
// in UTF-8 byte order. Late events (event time below the current watermark)
// are reported on lateLog with their physical line number and skipped. Every
// output must land in full: a window result is its complete JSON object plus
// trailing newline and a late-event notice is its complete single line. If
// the corresponding writer returns an error after accepting zero bytes or
// only a prefix, or accepts too few bytes with no error, the run fails at
// once with *OutputError naming the triggering physical input line:
// window-result failures identify the key and window [start,end), and
// late-notice failures identify the skipped event time and the watermark
// used; a nil-error short write is io.ErrShortWrite and errors.Is exposes
// the writer's original error. After such a failure no further records are
// processed, the failed content is neither rewritten nor resent, and
// still-open windows produce no further results; content already accepted
// by the writers stays in place, including fully written earlier results.
// Fatal record problems return *InputError; results already written to out
// stay written, and open windows are not flushed at end of input. An event
// key that would lose characters when decoded -- invalid UTF-8 bytes, or a
// \u escape whose surrogate half is unpaired or mispaired -- is such a fatal
// problem: it is never repaired to U+FFFD and counted, so distinct damaged
// keys can never merge or collide with a key that is genuinely U+FFFD. The
// check runs before the late-event check, so a damaged key is fatal even
// below the current watermark.
//
// A read failure is distinct from reaching the end of input. Only a reader
// returning the bare io.EOF sentinel is a clean end, where a final record that
// arrived without a trailing newline is still processed (and a damaged one is
// an *InputError carrying its physical line number). A wrapped io.EOF or a
// combined error whose chain merely contains io.EOF is still a read failure.
// When r returns any error other than the bare io.EOF after delivering bytes,
// only records whose newline was already received are processed, in order,
// including records returned by the same Read that carried the error; the
// remaining unterminated bytes never become an event, watermark or idle
// declaration and can produce no late notice or window result, and the
// reader's own error is then returned unchanged so errors.Is exposes it. A
// record or output failure on one of those complete lines is reported
// instead of the read error discovered afterwards.
//
// This is the legacy single-watermark mode: records carry no partition field
// and any extra fields are ignored. Use RunAggregatePartitioned to merge
// several independent input sources of the same stream, or
// RunAggregateSliding to emit overlapping windows at a shorter interval.
func RunAggregate(r io.Reader, windowMillis int64, out io.Writer, lateLog io.Writer) error {
	return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, 0, out, lateLog)
}

// RunAggregateSliding is RunAggregate with overlapping sliding windows. The
// window length is windowMillis and consecutive window starts are slideMillis
// apart, beginning at time zero: 0, slideMillis, 2*slideMillis, ... Each
// window is left-closed right-open and no window with a negative start is
// created. slideMillis must be a positive signed 64-bit integer no greater
// than windowMillis and does not have to divide it; slideMillis equal to
// windowMillis is exactly RunAggregate's fixed-window behavior. A valid event
// is counted once in every window that contains its event time, adding to
// that window's per-key count and the full value to its sum. Everything else
// (watermark-only closure, ordering, late reporting, overflow handling and
// end-of-input behavior) is identical to RunAggregate.
func RunAggregateSliding(r io.Reader, windowMillis, slideMillis int64, out io.Writer, lateLog io.Writer) error {
	return RunAggregatePartitionedSliding(r, windowMillis, slideMillis, 0, out, lateLog)
}

// RunAggregatePartitioned is RunAggregatePartitionedSliding with slideMillis
// equal to windowMillis (non-overlapping fixed windows).
func RunAggregatePartitioned(r io.Reader, windowMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
	return RunAggregatePartitionedSliding(r, windowMillis, windowMillis, partitions, out, lateLog)
}

// RunAggregatePartitionedSliding combines sliding windows (see
// RunAggregateSliding) with partitioned inputs: events from different
// partitions merge into one count and sum per key and window, and both the
// late-event check and window closure use the effective (minimum) watermark.
// windowMillis and slideMillis are validated exactly as in
// RunAggregateSliding. partitions selects the input mode:
//
//   - partitions == 0: legacy single-watermark mode. Records do not carry a
//     partition field; any extra fields are ignored.
//
//   - partitions > 0: partitioned mode, merging partitions independent input
//     sources of the same stream. Every event and watermark record must carry
//     an integer "partition" in [0,partitions). Each partition advances its
//     own watermark; no effective watermark exists until every partition has
//     reported at least once, afterwards the effective watermark is the
//     minimum of the per-partition values. Window closure and late-event
//     checks use this minimum, so one partition's larger watermark can never
//     close a window or drop an event ahead of the others. A partition
//     watermark may repeat or jump forward but never move backwards.
//
//     A partition may be declared idle with
//     {"type":"idle","partition":p}. An idle partition stops contributing to
//     the effective watermark: non-idle partitions that have not reported a
//     watermark yet still keep the effective watermark unknown, while a
//     partition that never reported may itself be declared idle. When every
//     remaining (non-idle) partition has reported, the effective watermark is
//     their minimum and the idle record itself can close windows. If all
//     partitions are idle, the last produced effective watermark is retained;
//     when none was ever produced it stays unknown. Idleness is declared by
//     the input only, never inferred from time; a repeated idle declaration
//     is a no-op. The next watermark record for that partition resumes it:
//     its time must be at least both the partition's previous watermark and
//     the current effective watermark. An event for an idle partition is
//     fatal; it never resumes implicitly.
//
// partitions < 0 is an error. Windows, ordering, late-event reporting,
// overflow checks and end-of-input behavior are otherwise identical to
// RunAggregateSliding.
func RunAggregatePartitionedSliding(r io.Reader, windowMillis, slideMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
	if err := ValidateAggregateParams(windowMillis, slideMillis, partitions); err != nil {
		return err
	}
	s := &aggregateState{
		windowMillis:  windowMillis,
		slideMillis:   slideMillis,
		windows:       make(map[windowID]*windowState),
		out:           out,
		lateLog:       lateLog,
		partitions:    partitions,
		partWatermark: make(map[int64]*int64),
		idle:          make(map[int64]bool),
		// Every partition starts out active and unreported; in legacy mode
		// (partitions == 0) the counter stays zero and is never consulted.
		unreportedActive: partitions,
	}

	// Read records with a line collector that keeps a read failure distinct
	// from end of input: only newline-terminated lines (plus, at a clean EOF,
	// one unterminated final line) ever become records.
	lineNo := 0
	err := readAggregateLines(r, func(line string, no int) error {
		lineNo = no
		if strings.TrimSpace(line) == "" {
			return nil
		}
		return s.processLine(line, lineNo)
	})
	return err
}

// maxAggregateLineBytes caps the size of a single physical input line, matching
// the scanner buffer limit this used to run with. A line this long is fatal
// before its record is parsed.
const maxAggregateLineBytes = 1024 * 1024 * 1024

// errAggregateLineTooLong reports a physical input line that never ends within
// maxAggregateLineBytes.
var errAggregateLineTooLong = errors.New("aggregate input line longer than 1 GiB")

// errAggregateBadReadCount reports an io.Reader that handed back a byte count
// outside the destination buffer, violating the io.Reader contract.
var errAggregateBadReadCount = errors.New("aggregate reader returned an impossible byte count")

// readAggregateLines feeds newline-delimited physical lines from r to handle,
// counting every line (a bare "\n" is a blank line too) and stripping a single
// trailing '\r' so CRLF input works as before. Clean end of input and a
// non-EOF read failure are handled differently: only the bare io.EOF
// sentinel is a clean end, and then a final line missing its newline is still
// delivered, exactly like every other final record; a wrapped io.EOF or a
// combined error whose chain contains io.EOF is a failure, not an end. After
// any error other than the bare io.EOF only lines whose newline was already
// received (including those delivered by the same Read that carried the
// error) are handled, in order, and then the reader's original error is
// returned. The unterminated tail never reaches handle, so a read failure
// mid-record can neither be misreported as an input error nor produce
// events, watermarks, idle declarations, late notices or window results. A
// non-nil error from handle stops reading immediately and replaces the read
// error, so an earlier record or output failure is not overwritten by a
// failure the reader only reports later.
func readAggregateLines(r io.Reader, handle func(line string, lineNo int) error) error {
	// buf[start:end] is the undelivered tail; buf[:start] is space freed by
	// already delivered lines. The buffer is compacted and grown like
	// bufio.Scanner's, so a long unterminated line is bounded by
	// maxAggregateLineBytes instead of growing without limit.
	//
	// searchFrom is the earliest absolute index not yet inspected for a '\n':
	// every byte before it has either been delivered or searched already. A
	// Read can only introduce a newline in the bytes it just appended, so the
	// pending tail of a long line is never rescanned; scanning, compaction and
	// growth together stay linear in the cumulative byte count even when each
	// Read brings a single byte. searchFrom >= start always holds, and
	// compaction/growth shift every absolute index by the same start they do.
	buf := make([]byte, 64*1024)
	start, end := 0, 0
	searchFrom := 0
	lineNo := 0
	emptyReads := 0
	deliver := func(b []byte) error {
		lineNo++
		line := strings.TrimSuffix(string(b), "\r")
		return handle(line, lineNo)
	}
	for {
		// Move the pending tail to the front when its freed prefix is large
		// enough or when the whole buffer is pending.
		if start > 0 && (end == len(buf) || start > len(buf)/2) {
			copy(buf, buf[start:end])
			end -= start
			searchFrom -= start
			if searchFrom < 0 {
				searchFrom = 0
			}
			start = 0
		}
		if end == len(buf) {
			// No newline fit before the end: the physical line is too long.
			if len(buf) >= maxAggregateLineBytes {
				return errAggregateLineTooLong
			}
			newLen := len(buf) * 2
			if newLen > maxAggregateLineBytes || newLen < len(buf) {
				newLen = maxAggregateLineBytes
			}
			grown := make([]byte, newLen)
			copy(grown, buf[start:end])
			buf = grown
			end -= start
			searchFrom -= start
			if searchFrom < 0 {
				searchFrom = 0
			}
			start = 0
		}
		n, readErr := r.Read(buf[end:])
		if n < 0 || n > len(buf)-end {
			// A Reader must never report a byte count outside the buffer.
			return errAggregateBadReadCount
		}
		end += n
		// Only this Read's newly appended bytes can still hold an unseen
		// newline; search from searchFrom rather than from start, so a long
		// line delivered a few bytes at a time costs one scan of each byte
		// instead of one scan per Read over the whole accumulated tail.
		for searchFrom < end {
			i := bytes.IndexByte(buf[searchFrom:end], '\n')
			if i < 0 {
				break
			}
			idx := searchFrom + i
			if err := deliver(buf[start:idx]); err != nil {
				return err
			}
			start = idx + 1
			searchFrom = start
		}
		searchFrom = end
		if readErr != nil {
			if readErr == io.EOF {
				// Clean end of input: a trailing line without a newline is a
				// complete final record; an empty tail (input ending exactly
				// on '\n') is nothing, not an extra blank line. Only the
				// bare io.EOF sentinel counts -- a wrapped EOF or a combined
				// error whose chain contains io.EOF is a read failure, never
				// a clean end.
				if end > start {
					if err := deliver(buf[start:end]); err != nil {
						return err
					}
				}
				return nil
			}
			// Any other failure means the stream stopped mid-record: the
			// still-unterminated bytes are not a record. Surface the original
			// error unchanged so errors.Is keeps working for callers.
			return readErr
		}
		if n == 0 {
			// No data and no error: refuse to spin forever on a broken Reader.
			emptyReads++
			if emptyReads > 100 {
				return io.ErrNoProgress
			}
		} else {
			emptyReads = 0
		}
	}
}

type aggregateState struct {
	windowMillis int64
	slideMillis  int64 // distance between consecutive window starts; equals windowMillis for fixed windows
	windows      map[windowID]*windowState
	out          io.Writer
	lateLog      io.Writer

	partitions    int64 // 0 = legacy single-watermark mode
	watermark     *int64
	partWatermark map[int64]*int64 // partition -> last watermark; partitioned mode only
	idle          map[int64]bool   // partitions declared idle in the input; partitioned mode only
	// unreportedActive counts the partitions that are neither idle nor have
	// reported a watermark yet; partitioned mode only. While it is positive
	// no effective watermark exists, so the waiting check is a single look at
	// this counter instead of a rescan of every partition's reporting state.
	// It never increases: a partition leaves the count by reporting or by
	// being declared idle, and resuming from idle always happens through a
	// watermark record, which reports at the same moment.
	unreportedActive int64
}

func (s *aggregateState) processLine(line string, lineNo int) error {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal([]byte(line), &obj); err != nil {
		return &InputError{Line: lineNo, Reason: "invalid JSON record: " + err.Error()}
	}

	typeRaw, ok := obj["type"]
	if !ok {
		return &InputError{Line: lineNo, Reason: `missing required string field "type"`}
	}
	recordType, err := decodeString(typeRaw, "type")
	if err != nil {
		return &InputError{Line: lineNo, Reason: err.Error()}
	}

	switch recordType {
	case "event":
		return s.processEvent(obj, lineNo)
	case "watermark":
		return s.processWatermark(obj, lineNo)
	case "idle":
		// Only partitioned mode knows idle declarations; legacy
		// single-watermark mode treats it as any unknown record type.
		if s.partitions == 0 {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
		}
		return s.processIdle(obj, lineNo)
	default:
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
	}
}

// floorDiv returns math.Floor(a/b) for b > 0; Go's / truncates toward zero,
// so negative numerators need explicit adjustment.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && a < 0 {
		q--
	}
	return q
}

// containingWindows describes every window that contains one event time, in
// one derivation shared by the normal counting path and the window-end
// overflow precheck: how many windows there are, where each starts, and which
// (if any) is the earliest whose end leaves the signed 64-bit range. Windows
// start at 0, slide, 2*slide, ... and none with a negative start is created,
// so the first index is clamped to zero. The last index is
// eventTime/slide, so an event at a window end is outside that window.
type containingWindows struct {
	count     int64 // how many windows contain the event time
	lastStart int64 // start of the last (highest) containing window
	slide     int64 // distance between consecutive window starts
	// firstOverflow is the start of the earliest containing window whose end
	// (start + windowMillis) leaves the signed 64-bit range, or -1 when every
	// containing window fits. Containing starts are an ascending arithmetic
	// sequence with step slide, so overflow (if any) is a suffix and this is
	// its first member.
	firstOverflow int64
}

// containingWindows derives the containing-window range for eventTime.
func (s *aggregateState) containingWindows(eventTime int64) containingWindows {
	last := eventTime / s.slideMillis
	first := floorDiv(eventTime-s.windowMillis, s.slideMillis) + 1
	if first < 0 {
		first = 0
	}
	w := containingWindows{
		count:         last - first + 1,
		lastStart:     eventTime - eventTime%s.slideMillis,
		slide:         s.slideMillis,
		firstOverflow: -1,
	}
	lowest := w.start(w.count - 1) // earliest containing start; never negative
	maxSafeStart := int64(math.MaxInt64 - s.windowMillis)
	switch {
	case lowest > maxSafeStart:
		w.firstOverflow = lowest
	default:
		safe := (maxSafeStart-lowest)/s.slideMillis + 1 // containing starts that fit
		if safe < w.count {
			// Reach back from lastStart, which is at most eventTime, so the
			// subtraction cannot leave the signed 64-bit range.
			w.firstOverflow = w.start(w.count - 1 - safe)
		}
	}
	return w
}

// start returns the start of the containing window reached back by offset
// indices from the last one (offset 0 = last window).
func (w containingWindows) start(offset int64) int64 {
	return w.lastStart - offset*w.slide
}

// eventRecord is one input event whose record content has already been
// interpreted and validated independently of aggregate state: key, time,
// value and (in partitioned mode) partition are final. Nothing about idle
// partitions, watermarks or windows has been inspected yet, so producing one
// never mutates -- or even reads -- window state.
type eventRecord struct {
	key       string
	time      int64
	value     int64
	partition int64 // partitioned mode only; always 0 in legacy mode
}

// parseEventRecord is the interpretation half of event intake. It reads and
// checks the record's own fields and never consults aggregate state, so field
// legality is fully decided before any idle, late or window rule runs. Fields
// are validated in the order they have always been rejected: key, then time,
// then value, then partition. The key is decoded strictly: an empty key,
// invalid UTF-8 bytes and an unpaired or mispaired surrogate half are record
// errors, never content repaired to U+FFFD that could merge keys. In legacy
// mode (partitioned == false) extra fields -- including any stray partition
// field -- stay ignored and partition is reported as zero.
func parseEventRecord(obj map[string]json.RawMessage, partitioned bool, partitionCount int64, lineNo int) (eventRecord, error) {
	key, err := requiredKey(obj, lineNo)
	if err != nil {
		return eventRecord{}, err
	}
	if key == "" {
		return eventRecord{}, &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
	}
	eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
	if err != nil {
		return eventRecord{}, err
	}
	value, err := requiredInt64(obj, "value", lineNo)
	if err != nil {
		return eventRecord{}, err
	}
	var partition int64
	if partitioned {
		partition, err = requiredPartitionField(obj, partitionCount, lineNo)
		if err != nil {
			return eventRecord{}, err
		}
	}
	return eventRecord{
		key:       key,
		time:      eventTime,
		value:     value,
		partition: partition,
	}, nil
}

func (s *aggregateState) processEvent(obj map[string]json.RawMessage, lineNo int) error {
	// Stage 1: interpret and validate the record's own content without
	// touching aggregate state.
	ev, err := parseEventRecord(obj, s.partitions > 0, s.partitions, lineNo)
	if err != nil {
		return err
	}
	// Stage 2: apply the validated event to aggregate state.
	return s.acceptEvent(ev, lineNo)
}

// acceptEvent is the state half of event intake: it applies one record that
// parseEventRecord has already fully validated, in the same order as before
// the split -- idle partition first, then the global-watermark late rule, and
// only afterwards the window counts. It never re-reads or re-validates record
// fields, so a field problem can never be downgraded to an idle failure or a
// late notice here. Partitioned mode judges lateness against the overall
// effective watermark; an event on an idle partition stays fatal and never
// resumes the partition implicitly. A strictly late event is skipped with the
// existing notice; an event time equal to the watermark still enters its
// windows.
func (s *aggregateState) acceptEvent(ev eventRecord, lineNo int) error {
	if s.partitions > 0 && s.idle[ev.partition] {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("event for idle partition %d is not allowed; send a watermark to resume it first", ev.partition)}
	}

	if s.watermark != nil && ev.time < *s.watermark {
		notice := fmt.Sprintf("line %d: late event time=%d below current watermark %d, skipped\n", lineNo, ev.time, *s.watermark)
		if err := writeFull(s.lateLog, []byte(notice)); err != nil {
			return &OutputError{
				Line:   lineNo,
				Kind:   "late-event notice",
				Detail: fmt.Sprintf("event time %d below current watermark %d", ev.time, *s.watermark),
				Err:    err,
			}
		}
		return nil
	}

	return s.applyEventToWindows(ev, lineNo)
}

// applyEventToWindows counts one accepted event in every window that contains
// its event time, one count and the full value per window. It only mutates
// window state; the caller has already settled field validity, idleness and
// lateness. The containing-window range is derived once and shared by the
// window-end overflow precheck and the counting loop, so both judge the exact
// same set of windows. The precheck runs before any window is touched;
// per-window count and sum overflows then fail on this triggering event in
// ascending window-start order rather than at watermark closure.
func (s *aggregateState) applyEventToWindows(ev eventRecord, lineNo int) error {
	wins := s.containingWindows(ev.time)

	// A window whose end leaves the signed 64-bit range is fatal for the
	// whole input line; check before updating any window state.
	if wins.firstOverflow >= 0 {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("window end overflow for key %q window starting at %d with length %d", ev.key, wins.firstOverflow, s.windowMillis)}
	}

	// Add the event once to each containing window, in ascending start
	// order. An overflow here stops processing immediately; already closed
	// (and thus already written) windows are unaffected.
	for i := wins.count - 1; i >= 0; i-- {
		if err := s.addEventToWindow(ev, wins.start(i), lineNo); err != nil {
			return err
		}
	}
	return nil
}

// addEventToWindow folds a single accepted event into one containing window,
// creating the window first if needed, enforcing the signed 64-bit count and
// cumulative-sum boundaries before the mutation. On failure the window keeps
// its previous count and sum and the error names the physical line, the key
// and this window's [start,end) interval.
func (s *aggregateState) addEventToWindow(ev eventRecord, start int64, lineNo int) error {
	end := start + s.windowMillis
	id := windowID{start: start, key: ev.key}
	st := s.windows[id]
	if st == nil {
		st = &windowState{end: end}
		s.windows[id] = st
	}
	if st.count == math.MaxInt64 {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", ev.key, start, end)}
	}
	if ev.value > 0 && st.sum > math.MaxInt64-ev.value {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", ev.key, start, end, st.sum, ev.value)}
	}
	if ev.value < 0 && st.sum < math.MinInt64-ev.value {
		return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", ev.key, start, end, st.sum, ev.value)}
	}
	st.count++
	st.sum += ev.value
	return nil
}

func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
	next, err := requiredNonNegInt64(obj, "time", lineNo)
	if err != nil {
		return err
	}
	p, err := s.requiredPartition(obj, lineNo)
	if err != nil {
		return err
	}

	if s.partitions == 0 {
		if s.watermark != nil && next < *s.watermark {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
		}
		s.watermark = &next
	} else {
		resuming := s.idle[p]
		if resuming {
			// A resume watermark must be at least the partition's previous
			// watermark and the effective watermark produced while it was
			// idle; equality on either boundary resumes.
			if prev, ok := s.partWatermark[p]; ok && next < *prev {
				return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below its previous watermark %d", next, p, *prev)}
			}
			if s.watermark != nil && next < *s.watermark {
				return &InputError{Line: lineNo, Reason: fmt.Sprintf("resume watermark %d for partition %d is below the current effective watermark %d", next, p, *s.watermark)}
			}
			delete(s.idle, p)
		} else if prev, ok := s.partWatermark[p]; ok && next < *prev {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *prev, next)}
		}
		if _, reported := s.partWatermark[p]; !reported && !resuming {
			// First report from an active partition: one fewer partition the
			// effective watermark still waits for. A resume reports too, but
			// a never-reported partition was already subtracted when it was
			// declared idle, so the count needs no change on this path. A
			// rejected (backwards) watermark returns above and never reaches
			// this decrement.
			s.unreportedActive--
		}
		s.partWatermark[p] = &next
	}

	// A watermark update and an idle declaration share one advance-and-close
	// path from here so both triggers follow the same rules.
	return s.advanceWatermark(lineNo)
}

// processIdle declares a partition idle: it stops contributing to the
// effective watermark until its next watermark record. The declaration
// itself may advance the effective watermark and close windows.
func (s *aggregateState) processIdle(obj map[string]json.RawMessage, lineNo int) error {
	p, err := s.requiredPartition(obj, lineNo)
	if err != nil {
		return err
	}
	if s.idle[p] {
		// A repeated idle declaration is a no-op: the partition already
		// stopped contributing, so neither the effective watermark nor the
		// set of closable windows can change.
		return nil
	}
	s.idle[p] = true
	if _, reported := s.partWatermark[p]; !reported {
		// An unreported partition that goes idle stops being waited on: one
		// fewer active partition the effective watermark still needs.
		s.unreportedActive--
	}
	// With the partition excluded, the remaining non-idle partitions
	// determine the effective watermark; the declaration itself can advance
	// it and close windows, exactly like a watermark update.
	return s.advanceWatermark(lineNo)
}

// advanceWatermark applies a partition state change -- a partition watermark
// update or an idle declaration -- and closes every window the resulting
// watermark allows. Both triggers funnel through here so they follow the
// same rules: in partitioned mode the effective watermark is recomputed from
// the current partition state (an active partition that has not reported yet
// keeps it unknown, and when every partition is idle the last produced value
// is retained instead of clearing); in legacy single-watermark mode the
// single watermark is used as is. While no effective watermark exists no
// window closes; otherwise closeWindows emits every window whose end is less
// than or equal to it.
func (s *aggregateState) advanceWatermark(lineNo int) error {
	if s.partitions > 0 {
		if next := s.effectiveWatermark(); next != nil {
			s.watermark = next
		}
	}
	if s.watermark == nil {
		return nil
	}
	return s.closeWindows(*s.watermark, lineNo)
}

// effectiveWatermark returns the minimum watermark over the non-idle
// partitions once each of them has reported at least once, or nil
// otherwise. When every partition is idle, nil is returned so the caller
// keeps the last produced effective watermark. The waiting check itself is
// the unreportedActive counter, maintained incrementally as partitions
// report or go idle, so a watermark or idle record that arrives while
// partitions are still silent costs one comparison rather than a rescan of
// every partition's reporting state; only once the counter reaches zero --
// every active partition has reported -- is the minimum computed by the
// scan below, exactly as before.
func (s *aggregateState) effectiveWatermark() *int64 {
	active := s.partitions - int64(len(s.idle))
	if active <= 0 || s.unreportedActive > 0 {
		return nil
	}
	var min int64
	first := true
	for p := int64(0); p < s.partitions; p++ {
		if s.idle[p] {
			continue
		}
		w, ok := s.partWatermark[p]
		if !ok {
			return nil
		}
		if first || *w < min {
			min = *w
			first = false
		}
	}
	return &min
}

// requiredPartition returns the record's partition index. In legacy mode it
// returns 0 without inspecting the record, so extra fields stay ignored. In
// partitioned mode the actual reading and range checking lives in the shared
// free function used by event interpretation as well.
func (s *aggregateState) requiredPartition(obj map[string]json.RawMessage, lineNo int) (int64, error) {
	if s.partitions == 0 {
		return 0, nil
	}
	return requiredPartitionField(obj, s.partitions, lineNo)
}

// requiredPartitionField reads and range-checks a partitioned-mode record's
// "partition" field. It is pure record interpretation: the partition count is
// passed in rather than read from aggregate state, so both the event intake
// split (parseEventRecord) and the watermark/idle paths validate the field by
// the exact same rule without touching window state.
func requiredPartitionField(obj map[string]json.RawMessage, partitionCount int64, lineNo int) (int64, error) {
	p, err := requiredInt64(obj, "partition", lineNo)
	if err != nil {
		return 0, err
	}
	if p < 0 || p >= partitionCount {
		return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be an integer in range [0,%d), got %d", "partition", partitionCount, p)}
	}
	return p, nil
}

func (s *aggregateState) closeWindows(watermark int64, lineNo int) error {
	type pending struct {
		id windowID
		st *windowState
	}
	var ready []pending
	for id, st := range s.windows {
		if st.end <= watermark {
			ready = append(ready, pending{id: id, st: st})
		}
	}
	sort.Slice(ready, func(i, j int) bool {
		if ready[i].st.end != ready[j].st.end {
			return ready[i].st.end < ready[j].st.end
		}
		return ready[i].id.key < ready[j].id.key
	})
	for _, p := range ready {
		encoded, err := json.Marshal(AggregateResult{
			Key:   p.id.key,
			Start: p.id.start,
			End:   p.st.end,
			Count: p.st.count,
			Sum:   p.st.sum,
		})
		if err != nil {
			return err
		}
		line := append(encoded, '\n')
		if err := writeFull(s.out, line); err != nil {
			// Stop immediately: the writer may hold zero bytes or only a
			// prefix of this record, but a truncated record is not a fully
			// output one, so the window stays open in the map. Do not retry
			// or resend it and do not emit the remaining ready windows;
			// content already accepted by the writer stays.
			return &OutputError{
				Line:   lineNo,
				Kind:   "window result",
				Detail: fmt.Sprintf("key %q window [%d,%d)", p.id.key, p.id.start, p.st.end),
				Err:    err,
			}
		}
		delete(s.windows, p.id)
	}
	return nil
}

func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
	raw, ok := obj[field]
	if !ok {
		return "", &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required string field %q", field)}
	}
	value, err := decodeString(raw, field)
	if err != nil {
		return "", &InputError{Line: lineNo, Reason: err.Error()}
	}
	return value, nil
}

// requiredKey returns the event key decoded strictly. encoding/json silently
// repairs damaged string content with U+FFFD -- invalid UTF-8 bytes and \u
// escapes whose surrogate halves are unpaired or mispaired -- which would
// merge distinct damaged keys into one and collide with a key that is
// genuinely U+FFFD. Such damage is a fatal input error here instead, so a
// corrupt key never changes any window's count or sum. Valid characters
// (including a directly encoded or escaped U+FFFD and supplementary-plane
// characters, whether literal or written as a surrogate pair) decode to
// their exact value and aggregate as before.
func requiredKey(obj map[string]json.RawMessage, lineNo int) (string, error) {
	raw, ok := obj["key"]
	if !ok {
		return "", &InputError{Line: lineNo, Reason: `missing required string field "key"`}
	}
	key, err := decodeKeyString(raw)
	if err != nil {
		return "", &InputError{Line: lineNo, Reason: err.Error()}
	}
	return key, nil
}

// decodeKeyString decodes the event key's JSON string without the lossy
// repairs encoding/json applies: invalid UTF-8 byte sequences and \u escapes
// with unpaired or mispaired surrogate halves are errors instead of becoming
// U+FFFD. The record already parsed as JSON, so the string's escape syntax
// is valid; only its character content is checked here. An escaped backslash
// is decoded first, so "\\uD800" stays the literal text D800 and is not
// mistaken for an unpaired surrogate.
func decodeKeyString(raw json.RawMessage) (string, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) < 2 || trimmed[0] != '"' || trimmed[len(trimmed)-1] != '"' {
		return "", fmt.Errorf("field %q must be a JSON string, got %s", "key", string(trimmed))
	}
	s := string(trimmed[1 : len(trimmed)-1])
	var sb strings.Builder
	sb.Grow(len(s))
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == '\\':
			if i+1 >= len(s) {
				return "", fmt.Errorf("field %q ends in an incomplete escape", "key")
			}
			switch s[i+1] {
			case '"', '\\', '/':
				sb.WriteByte(s[i+1])
				i += 2
			case 'b':
				sb.WriteByte('\b')
				i += 2
			case 'f':
				sb.WriteByte('\f')
				i += 2
			case 'n':
				sb.WriteByte('\n')
				i += 2
			case 'r':
				sb.WriteByte('\r')
				i += 2
			case 't':
				sb.WriteByte('\t')
				i += 2
			case 'u':
				r, next, err := decodeUnicodeEscape(s, i)
				if err != nil {
					return "", err
				}
				sb.WriteRune(r)
				i = next
			default:
				return "", fmt.Errorf("field %q has an invalid escape \\%c", "key", s[i+1])
			}
		case c < utf8.RuneSelf:
			sb.WriteByte(c)
			i++
		default:
			r, size := utf8.DecodeRuneInString(s[i:])
			if r == utf8.RuneError && size == 1 {
				return "", fmt.Errorf("field %q contains invalid UTF-8 bytes in its character encoding", "key")
			}
			sb.WriteString(s[i : i+size])
			i += size
		}
	}
	return sb.String(), nil
}

// decodeUnicodeEscape decodes the \uXXXX escape at s[i] (where s[i] == '\\'
// and s[i+1] == 'u'), returning the decoded rune and the index just past the
// escape. A high surrogate must be immediately followed by a \u escape
// carrying the matching low surrogate; the pair combines into one
// supplementary-plane rune. An unpaired or mispaired half is an error rather
// than U+FFFD.
func decodeUnicodeEscape(s string, i int) (rune, int, error) {
	r, next, err := parseHexEscape(s, i)
	if err != nil {
		return 0, 0, err
	}
	switch {
	case r >= 0xD800 && r <= 0xDBFF:
		if next+1 >= len(s) || s[next] != '\\' || s[next+1] != 'u' {
			return 0, 0, fmt.Errorf("field %q has an unpaired high surrogate in a Unicode escape", "key")
		}
		lo, after, err := parseHexEscape(s, next)
		if err != nil {
			return 0, 0, err
		}
		if lo < 0xDC00 || lo > 0xDFFF {
			return 0, 0, fmt.Errorf("field %q has a high surrogate not followed by a low surrogate in a Unicode escape", "key")
		}
		return 0x10000 + (r-0xD800)<<10 + (lo - 0xDC00), after, nil
	case r >= 0xDC00 && r <= 0xDFFF:
		return 0, 0, fmt.Errorf("field %q has an unpaired low surrogate in a Unicode escape", "key")
	}
	return r, next, nil
}

// parseHexEscape reads the four hex digits of the \uXXXX escape at s[i]
// (where s[i] == '\\' and s[i+1] == 'u') and returns their value and the
// index just past them.
func parseHexEscape(s string, i int) (rune, int, error) {
	if i+6 > len(s) {
		return 0, 0, fmt.Errorf("field %q has a truncated Unicode escape", "key")
	}
	var v rune
	for _, c := range s[i+2 : i+6] {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v += c - '0'
		case c >= 'a' && c <= 'f':
			v += c - 'a' + 10
		case c >= 'A' && c <= 'F':
			v += c - 'A' + 10
		default:
			return 0, 0, fmt.Errorf("field %q has a non-hex digit in a Unicode escape", "key")
		}
	}
	return v, i + 6, nil
}

func requiredInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
	raw, ok := obj[field]
	if !ok {
		return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required integer field %q", field)}
	}
	value, err := decodeInt64(raw, field)
	if err != nil {
		return 0, &InputError{Line: lineNo, Reason: err.Error()}
	}
	return value, nil
}

func requiredNonNegInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
	value, err := requiredInt64(obj, field, lineNo)
	if err != nil {
		return 0, err
	}
	if value < 0 {
		return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be a non-negative integer, got %d", field, value)}
	}
	return value, nil
}

func decodeString(raw json.RawMessage, field string) (string, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '"' {
		return "", fmt.Errorf("field %q must be a JSON string, got %s", field, string(trimmed))
	}
	var value string
	if err := json.Unmarshal(trimmed, &value); err != nil {
		return "", fmt.Errorf("field %q must be a JSON string: %v", field, err)
	}
	return value, nil
}

func decodeInt64(raw json.RawMessage, field string) (int64, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return 0, fmt.Errorf("field %q must be a signed 64-bit integer", field)
	}
	switch trimmed[0] {
	case '"', '{', '[', 't', 'f', 'n':
		return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
	}
	value, err := strconv.ParseInt(string(trimmed), 10, 64)
	if err != nil {
		if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
			return 0, fmt.Errorf("field %q integer out of signed 64-bit range: %s", field, string(trimmed))
		}
		return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
	}
	return value, nil
}

package edgefleet

import (
	"errors"
	"math"
	"strings"
	"testing"
)

// Regression safeguards for the ordering between record validation and the
// late-event judgement in partitioned sliding mode (window 1000, slide 600,
// two partitions whose watermarks already differ and whose effective
// (minimum) watermark is established):
//
//   - A record whose own fields are invalid must fail with *InputError at its
//     physical line even when its event time is strictly below the effective
//     watermark (and still inside an unclosed overlapping window). It must
//     never be absorbed as a normal late-event skip, and it must never be
//     blamed on a window cumulative-sum overflow that the record never reached.
//   - A record with every field legal is judged late against the EFFECTIVE
//     watermark and skipped with exactly one notice, changing no window. Its
//     value may be a legal integer that would overflow the open window's
//     accumulated sum: the skip still wins over the sum check.
//   - An event with time exactly equal to the effective watermark is not late:
//     it joins the window containing it and the window closes with the right
//     count and sum once the minimum watermark allows. The fast partition's
//     own, larger watermark can neither judge lateness nor close windows by
//     itself.
//
// Blank physical lines count toward the line number in every scenario.

// lateFieldOrderPrefix builds the shared history (window 1000, slide 600,
// partitions 2):
//
//	line 1: blank (physical lines count)
//	line 2: event k time=900 value=7 partition 0 -> [0,1000) and [600,1600)
//	line 3: watermark 5000 partition 0           -> fast partition races ahead
//	line 4: watermark 1000 partition 1           -> effective min = 1000;
//	                                               closes only [0,1000);
//	                                               [600,1600) stays open
//	line 5: blank
//
// so a time=999 record on line 6 is strictly below the effective watermark
// 1000 (yet still inside the open [600,1600)), and partition 0's own
// watermark 5000 is not the value that judges it.
func lateFieldOrderPrefix() []string {
	return []string{
		``, // line 1 blank
		`{"type":"event","key":"k","time":900,"value":7,"partition":0}`, // line 2
		`{"type":"watermark","time":5000,"partition":0}`,                // line 3
		`{"type":"watermark","time":1000,"partition":1}`,                // line 4: effective = 1000
		``, // line 5 blank
	}
}

// lateFieldOrderSuffix are the records that must be completely dead after a
// fatal record error on line 6:
//
//	line 6 would hold the bad record (supplied by the caller)
//	line 7: legal event at time == watermark 1000, would enter [600,1600)
//	line 8: legal time=998 event, would log another late notice if reached
//	line 9: watermark 1600 partition 1, would close [600,1600) if reached
func lateFieldOrderSuffix() []string {
	return []string{
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`, // line 7
		`{"type":"event","key":"k","time":998,"value":1,"partition":1}`,  // line 8 late if reached
		`{"type":"watermark","time":1600,"partition":1}`,                 // line 9
	}
}

var lateFieldOrderWantFirstWindow = `{"key":"k","start":0,"end":1000,"count":1,"sum":7}` + "\n"

// TestSlidingPartitionInvalidLateRecordIsInputError covers every invalid
// field shape on an event that is unambiguously late (time 999 < effective
// watermark 1000) and still inside the open [600,1600): value missing, value
// written as a string, value outside signed 64-bit range, and (with a legal
// value) partition missing or out of the configured range. Each must be an
// *InputError on physical line 6 naming the offending field and the concrete
// reason -- not a late-event skip, not a cumulative sum overflow. Earlier
// fully written output is retained, the open window is not retroactively
// emitted, and no later result or late notice may appear.
func TestSlidingPartitionInvalidLateRecordIsInputError(t *testing.T) {
	cases := []struct {
		name      string
		record    string
		wantField string // the field name the reason must quote
		wantCause string // a distinctive substring of the concrete reason
	}{
		{
			name:      "value missing",
			record:    `{"type":"event","key":"k","time":999,"partition":1}`,
			wantField: `"value"`,
			wantCause: `missing required integer field "value"`,
		},
		{
			name:      "value written as string",
			record:    `{"type":"event","key":"k","time":999,"value":"oops","partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" must be a signed 64-bit integer, got "oops"`,
		},
		{
			name:      "value above signed 64-bit range",
			record:    `{"type":"event","key":"k","time":999,"value":9223372036854775808,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: 9223372036854775808`,
		},
		{
			name:      "value below signed 64-bit range",
			record:    `{"type":"event","key":"k","time":999,"value":-9223372036854775809,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: -9223372036854775809`,
		},
		{
			name:      "partition missing with legal value",
			record:    `{"type":"event","key":"k","time":999,"value":1}`,
			wantField: `"partition"`,
			wantCause: `missing required integer field "partition"`,
		},
		{
			name:      "partition out of configured range with legal value",
			record:    `{"type":"event","key":"k","time":999,"value":1,"partition":9}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := append(lateFieldOrderPrefix(), tc.record)
			lines = append(lines, lateFieldOrderSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)

			if err == nil {
				t.Fatalf("an invalid late record must fail fatally; got nil, stdout=%q stderr=%q", stdout, stderr)
			}
			var inputErr *InputError
			if !errors.As(err, &inputErr) {
				t.Fatalf("want *InputError, got %T: %v", err, err)
			}
			var outputErr *OutputError
			if errors.As(err, &outputErr) {
				t.Fatalf("a malformed record must not be reported as an output failure: %v", err)
			}
			// Blank lines 1 and 5 still occupy physical numbers.
			if inputErr.Line != 6 {
				t.Errorf("InputError.Line = %d, want 6 (blank physical lines count)", inputErr.Line)
			}
			if !strings.Contains(inputErr.Reason, tc.wantField) {
				t.Errorf("reason %q must name field %s", inputErr.Reason, tc.wantField)
			}
			if !strings.Contains(inputErr.Reason, tc.wantCause) {
				t.Errorf("reason %q must state the concrete cause %q", inputErr.Reason, tc.wantCause)
			}
			// The record never reached window accumulation: it must not be
			// mislabelled as a cumulative sum overflow, and the physical line
			// must carry the field error rather than anything window-shaped.
			if strings.Contains(inputErr.Reason, "cumulative sum overflow") ||
				strings.Contains(inputErr.Reason, "window [") {
				t.Errorf("a field error below the watermark must not be blamed on window accumulation: %q", inputErr.Reason)
			}
			if strings.Contains(err.Error(), "late event") {
				t.Errorf("an invalid record must not be described as a late-event skip: %q", err.Error())
			}

			// No late notice for the bad record itself nor for the dead line 8.
			if stderr != "" {
				t.Errorf("late log must stay empty when the record itself is invalid; got %q", stderr)
			}
			// The fully written [0,1000) result stays exactly as published; the
			// still-open [600,1600) is not flushed and line 9 never closes it.
			if stdout != lateFieldOrderWantFirstWindow {
				t.Errorf("window output mismatch:\n got: %q\nwant: %q", stdout, lateFieldOrderWantFirstWindow)
			}
		})
	}
}

// TestSlidingPartitionValidLateRecordSkipsWithoutSumError is the control for
// the cases above: the same history and the same physical line 6, but the
// record's fields are all legal. It is judged against the effective watermark
// 1000 (partition 0 is already at 5000 and must not substitute that), and the
// open [600,1600) already holds math.MaxInt64, so its value 1 would overflow
// the cumulative sum if it were ever added. The late check wins: exactly one
// notice naming line 6, time 999 and watermark 1000 is written, processing
// continues, and no window count or sum changes due to that event. A legal
// event at time exactly 1000 then joins [600,1600) (value 0 moves only the
// count); repeating partition 0's watermark 5000 closes nothing, and the
// minimum watermark reaching 1600 emits the correct totals.
func TestSlidingPartitionValidLateRecordSkipsWithoutSumError(t *testing.T) {
	const M = math.MaxInt64
	lines := []string{
		``, // line 1 blank
		// Enters [0,1000) and [600,1600); both accumulate to MaxInt64.
		`{"type":"event","key":"big","time":900,"value":9223372036854775807,"partition":0}`, // line 2
		`{"type":"watermark","time":5000,"partition":0}`,                                    // line 3: fast partition ahead
		`{"type":"watermark","time":1000,"partition":1}`,                                    // line 4: effective 1000
		``, // line 5 blank
		// Fields legal; 999 < effective 1000 although 999 is inside the open
		// [600,1600), and value 1 would take that window's MaxInt64 over the
		// top. It must be skipped with one notice, never a sum error.
		`{"type":"event","key":"big","time":999,"value":1,"partition":1}`, // line 6 late
		// Time exactly equal to the effective watermark: not late, joins the
		// only window containing 1000, [600,1600); value 0 moves count only.
		`{"type":"event","key":"big","time":1000,"value":0,"partition":1}`, // line 7
		`{"type":"watermark","time":5000,"partition":0}`,                   // line 8: min stays 1000, closes nothing
		`{"type":"watermark","time":1600,"partition":1}`,                   // line 9: min = 1600 closes [600,1600)
	}
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("a legal late event must skip, not fail even at the sum boundary: %v", err)
	}
	wantNotice := "line 6: late event time=999 below current watermark 1000, skipped\n"
	if stderr != wantNotice {
		t.Fatalf("late notice mismatch:\n got: %q\nwant: %q", stderr, wantNotice)
	}
	// The notice judges against the effective minimum, never p0's own 5000.
	if strings.Count(stderr, "skipped\n") != 1 {
		t.Errorf("late event must be reported exactly once, got %q", stderr)
	}
	if strings.Contains(stderr, "5000") {
		t.Errorf("latency must be judged by the effective watermark 1000, not the fast partition's 5000: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"big","start":0,"end":1000,"count":1,"sum":9223372036854775807}`,
		// The skipped event added neither count nor value; the time==1000 event
		// moved only the count, and the sum rests exactly on MaxInt64.
		`{"key":"big","start":600,"end":1600,"count":2,"sum":9223372036854775807}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	// Reparse to pin the exact signed 64-bit totals the notices must not touch.
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "big", Start: 0, End: 1000, Count: 1, Sum: M},
		{Key: "big", Start: 600, End: 1600, Count: 2, Sum: M},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// TestSlidingPartitionInvalidLateRecordControlIsActuallyLate proves the
// history used above genuinely sits below the watermark: with the bad field
// repaired, the line-6 record is skipped as a normal late event exactly once
// and aggregation proceeds, closing [600,1600) later on the legitimate
// contributions alone (count 2, sum 10 -- the skipped value 1 adds nothing).
func TestSlidingPartitionInvalidLateRecordControlIsActuallyLate(t *testing.T) {
	lines := append(lateFieldOrderPrefix(),
		`{"type":"event","key":"k","time":999,"value":1,"partition":1}`, // line 6: same shape, now valid
	)
	lines = append(lines, lateFieldOrderSuffix()...)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("control record is valid and must not fail: %v", err)
	}
	wantNotices := strings.Join([]string{
		"line 6: late event time=999 below current watermark 1000, skipped",
		"line 8: late event time=998 below current watermark 1000, skipped",
		"",
	}, "\n")
	if stderr != wantNotices {
		t.Fatalf("late notices mismatch:\n got: %q\nwant: %q", stderr, wantNotices)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":7}`,
		// line 2's 7 and line 7's time==watermark 3; the late lines add
		// nothing: count 2 / sum 10.
		`{"key":"k","start":600,"end":1600,"count":2,"sum":10}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

package edgefleet

import (
	"errors"
	"strings"
	"testing"
)

// Regression safeguards for the error priority when an event arrives for a
// partition that has declared itself idle in partitioned sliding mode
// (window 1000, slide 600, two partitions, one key "k"). The ordering under
// protection is the intake order the public entry point has always applied:
//
//  1. The record's own content is interpreted and checked first -- key, then
//     time, then value, then partition (parseEventRecord).
//  2. Only afterwards is the partition's idle state consulted (acceptEvent).
//  3. The late-event judgement against the overall (minimum) watermark runs
//     last.
//
// So an event on an idle partition whose own fields are damaged must fail as a
// record error, never be downgraded to the "event for idle partition" failure
// or to a late-event notice -- even when its event time is strictly below the
// overall watermark while still falling in an overlapping window that has not
// closed. Integrators rely on the returned reason to tell corrupt data apart
// from a send-ordering mistake.
//
// The shared history (idleFieldOrderFixtureLines):
//
//	line 1: p0 event time=700  value=2 -> [0,1000) and [600,1600)
//	line 2: p1 event time=1000 value=3 -> [600,1600)
//	line 3: p0 watermark 1000
//	line 4: p1 declares idle           -> overall watermark 1000; closes [0,1000)
//	line 5: p0 watermark 1500          -> p1 idle, overall watermark 1500;
//	                                      [600,1600) (end 1600) stays open
//	line 6: blank (physical lines count)
//
// Afterwards partition 1 is idle, the overall watermark is 1500, [0,1000) has
// already been emitted (count 1, sum 2) and the overlapping [600,1600) still
// waits with the two pre-idle events (count 2, sum 5). A time=999 record on
// physical line 7 is both (a) on idle partition 1, (b) strictly below the
// overall watermark 1500, and (c) still inside the open [600,1600). This is
// exactly the three-way overlap the priority rule has to disambiguate.

// idleFieldOrderFixtureLines builds the shared history described above.
func idleFieldOrderFixtureLines() []string {
	return []string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,  // line 1
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`, // line 2
		`{"type":"watermark","time":1000,"partition":0}`,                 // line 3
		`{"type":"idle","partition":1}`,                                  // line 4: overall = 1000, closes [0,1000)
		`{"type":"watermark","time":1500,"partition":0}`,                 // line 5: p1 idle; overall = 1500
		``, // line 6: blank, still occupies a physical line number
	}
}

// idleFieldOrderBadLine is the physical line (7) carrying the record under
// test; idleFieldOrderDeadSuffix are the records that must stay completely
// dead after a fatal line-7 failure:
//
//	line 7 would hold the bad record (supplied by the caller)
//	line 8: legal p0 event at time == watermark 1500, would enter [600,1600)
//	line 9: legal p0 event at time 998, would log another late notice if reached
//	line 10: p0 watermark 2200, would close [600,1600) (and [1200,2200)) if reached
func idleFieldOrderDeadSuffix() []string {
	return []string{
		`{"type":"event","key":"k","time":1500,"value":4,"partition":0}`, // line 8
		`{"type":"event","key":"k","time":998,"value":8,"partition":0}`,  // line 9: late if reached
		`{"type":"watermark","time":2200,"partition":0}`,                 // line 10
	}
}

var idleFieldOrderWantFirstWindow = `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"

// assertIdleFieldRecordError checks the contract shared by every malformed
// record on the idle partition: an *InputError (never an *OutputError) on
// physical line 7, whose reason names wantField and states wantCause, with no
// trace of the idle-partition rule, a late-event skip or window accumulation.
// The bad record and the dead suffix write no late notice, and stdout keeps
// only the window closed before line 7; the still-open overlapping window is
// never back-filled.
func assertIdleFieldRecordError(t *testing.T, stdout, stderr string, err error, wantField, wantCause string) {
	t.Helper()
	if err == nil {
		t.Fatalf("a malformed idle-partition record must fail fatally; got nil, stdout=%q stderr=%q", stdout, stderr)
	}
	var inputErr *InputError
	if !errors.As(err, &inputErr) {
		t.Fatalf("want *InputError, got %T: %v", err, err)
	}
	var outputErr *OutputError
	if errors.As(err, &outputErr) {
		t.Fatalf("a malformed record must not be reported as an output failure: %v", err)
	}
	// Blank physical line 6 still occupies its number.
	if inputErr.Line != 7 {
		t.Errorf("InputError.Line = %d, want 7 (blank physical line 6 counts)", inputErr.Line)
	}
	if wantField != "" && !strings.Contains(inputErr.Reason, wantField) {
		t.Errorf("reason %q must name field %s", inputErr.Reason, wantField)
	}
	if !strings.Contains(inputErr.Reason, wantCause) {
		t.Errorf("reason %q must state the concrete cause %q", inputErr.Reason, wantCause)
	}
	// Content validation wins over both state-based judgements: the reason
	// must not be the idle hint or the late-event wording.
	if strings.Contains(inputErr.Reason, "idle partition") {
		t.Errorf("a field error must be reported before the idle-partition rule, reason %q", inputErr.Reason)
	}
	if strings.Contains(err.Error(), "late event") {
		t.Errorf("a damaged record must not be described as a late-event skip: %q", err.Error())
	}
	// The record never reached window accumulation; it must not be blamed on a
	// sum overflow or a window interval.
	if strings.Contains(inputErr.Reason, "overflow") || strings.Contains(inputErr.Reason, "window [") {
		t.Errorf("a field error must not be blamed on window accumulation: %q", inputErr.Reason)
	}
	// No late notice for the bad record itself nor for the dead line 9.
	if stderr != "" {
		t.Errorf("late log must stay empty for a damaged record and its dead suffix; got %q", stderr)
	}
	// The fully written [0,1000) result stays exactly as published; the open
	// [600,1600) is not flushed and the dead line-10 watermark never closes it.
	if stdout != idleFieldOrderWantFirstWindow {
		t.Errorf("window output mismatch:\n got: %q\nwant: %q", stdout, idleFieldOrderWantFirstWindow)
	}
}

// TestSlidingIdlePartitionDamagedRecordBeatsIdleAndLate is the core case. The
// line-7 event is on idle partition 1, has time 999 (strictly below the
// overall watermark 1500) yet still lies in the unclosed overlapping
// [600,1600). Every damaged-key and bad-field shape must nevertheless be the
// *InputError on physical line 7 naming the offending field and reason: a
// corrupt key (invalid UTF-8 bytes, an unpaired or mispaired Unicode
// surrogate, a missing or non-string key), a bad time, a missing /
// wrong-typed / out-of-int64-range value, and a missing or out-of-range
// partition. None may be masked by the idle hint or by a late notice.
func TestSlidingIdlePartitionDamagedRecordBeatsIdleAndLate(t *testing.T) {
	cases := []struct {
		name      string
		record    string
		wantField string
		wantCause string
	}{
		// --- key damage: character-encoding corruption, reported as data error
		{
			name:      "invalid raw UTF-8 bytes in key",
			record:    "{\"type\":\"event\",\"key\":\"a\xffb\",\"time\":999,\"value\":1,\"partition\":1}",
			wantField: `"key"`,
			wantCause: `field "key" contains invalid UTF-8 bytes in its character encoding`,
		},
		{
			name:      "unpaired high surrogate in key",
			record:    `{"type":"event","key":"bad\ud800k","time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `field "key" has an unpaired high surrogate in a Unicode escape`,
		},
		{
			name:      "unpaired low surrogate in key",
			record:    `{"type":"event","key":"bad\udc00k","time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `field "key" has an unpaired low surrogate in a Unicode escape`,
		},
		{
			name:      "high surrogate not followed by a low surrogate in key",
			record:    `{"type":"event","key":"bad\ud800Ak","time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `field "key" has an unpaired high surrogate in a Unicode escape`,
		},
		{
			name:      "key missing",
			record:    `{"type":"event","time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `missing required string field "key"`,
		},
		{
			name:      "key not a JSON string",
			record:    `{"type":"event","key":7,"time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `field "key" must be a JSON string, got 7`,
		},
		{
			name:      "empty key",
			record:    `{"type":"event","key":"","time":999,"value":1,"partition":1}`,
			wantField: `"key"`,
			wantCause: `field "key" must be a non-empty string`,
		},
		// --- the remaining fields, after a legal key
		{
			name:      "time missing",
			record:    `{"type":"event","key":"z","value":1,"partition":1}`,
			wantField: `"time"`,
			wantCause: `missing required integer field "time"`,
		},
		{
			name:      "value missing",
			record:    `{"type":"event","key":"z","time":999,"partition":1}`,
			wantField: `"value"`,
			wantCause: `missing required integer field "value"`,
		},
		{
			name:      "value written as a string",
			record:    `{"type":"event","key":"z","time":999,"value":"oops","partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" must be a signed 64-bit integer, got "oops"`,
		},
		{
			name:      "value above signed 64-bit range",
			record:    `{"type":"event","key":"z","time":999,"value":9223372036854775808,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: 9223372036854775808`,
		},
		{
			name:      "value below signed 64-bit range",
			record:    `{"type":"event","key":"z","time":999,"value":-9223372036854775809,"partition":1}`,
			wantField: `"value"`,
			wantCause: `field "value" integer out of signed 64-bit range: -9223372036854775809`,
		},
		{
			name:      "partition missing with legal value",
			record:    `{"type":"event","key":"z","time":999,"value":1}`,
			wantField: `"partition"`,
			wantCause: `missing required integer field "partition"`,
		},
		{
			name:      "partition out of configured range with legal value",
			record:    `{"type":"event","key":"z","time":999,"value":1,"partition":9}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := append(idleFieldOrderFixtureLines(), tc.record)
			lines = append(lines, idleFieldOrderDeadSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
			assertIdleFieldRecordError(t, stdout, stderr, err, tc.wantField, tc.wantCause)
		})
	}
}

// TestSlidingIdlePartitionFieldOrderIsKeyTimeValuePartition pins the
// validation order when a single line-7 event carries several field errors at
// once: the first error encountered in the fixed key, time, value, partition
// order is the one returned, regardless of which other fields are also wrong.
// Reordering how the fields are written in the JSON must not change the line
// number or the reason -- the textual order is irrelevant.
func TestSlidingIdlePartitionFieldOrderIsKeyTimeValuePartition(t *testing.T) {
	cases := []struct {
		name      string
		a         string // one JSON field spelling
		b         string // the same fields in a different textual order
		wantField string
		wantCause string
	}{
		{
			name:      "broken key and broken value: key wins",
			a:         `{"type":"event","key":"bad\ud800k","time":999,"value":"x","partition":1}`,
			b:         `{"type":"event","partition":1,"value":"x","time":999,"key":"bad\ud800k"}`,
			wantField: `"key"`,
			wantCause: `unpaired high surrogate`,
		},
		{
			name:      "legal key, broken time and broken value: time wins",
			a:         `{"type":"event","key":"z","time":"999","value":"x","partition":1}`,
			b:         `{"type":"event","partition":1,"value":"x","time":"999","key":"z"}`,
			wantField: `"time"`,
			wantCause: `field "time" must be a signed 64-bit integer, got "999"`,
		},
		{
			name:      "legal key and time, broken value and broken partition: value wins",
			a:         `{"type":"event","key":"z","time":999,"value":"x","partition":9}`,
			b:         `{"type":"event","partition":9,"value":"x","time":999,"key":"z"}`,
			wantField: `"value"`,
			wantCause: `field "value" must be a signed 64-bit integer, got "x"`,
		},
		{
			name:      "legal key time value, partition out of range: partition is the first error",
			a:         `{"type":"event","key":"z","time":999,"value":1,"partition":9}`,
			b:         `{"type":"event","partition":9,"value":1,"time":999,"key":"z"}`,
			wantField: `"partition"`,
			wantCause: `field "partition" must be an integer in range [0,2), got 9`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			first := runIdleFieldError(t, tc.a)
			second := runIdleFieldError(t, tc.b)
			if first.Line != 7 || second.Line != 7 {
				t.Errorf("line numbers = %d and %d, want 7 for both JSON field orders", first.Line, second.Line)
			}
			if first.Reason != second.Reason {
				t.Errorf("JSON field order changed the first error:\n order a: %q\n order b: %q", first.Reason, second.Reason)
			}
			if !strings.Contains(first.Reason, tc.wantField) {
				t.Errorf("reason %q must name %s", first.Reason, tc.wantField)
			}
			if !strings.Contains(first.Reason, tc.wantCause) {
				t.Errorf("reason %q must state %q", first.Reason, tc.wantCause)
			}
			if strings.Contains(first.Reason, "idle partition") {
				t.Errorf("the field error must precede the idle-partition rule: %q", first.Reason)
			}
		})
	}
}

// TestSlidingIdlePartitionLegalFieldsReportsIdle is the second-priority rule:
// when every field is legal but the partition is still idle, the run fails on
// the idle rule with the resume hint -- not a late notice -- even for an event
// time strictly below the overall watermark (999 < 1500) and for an event time
// exactly equal to it. Equality with the overall watermark must not let the
// event slip through: an idle partition can only be resumed by a watermark
// record. The dead suffix stays dead and the open overlapping window is never
// back-filled.
func TestSlidingIdlePartitionLegalFieldsReportsIdle(t *testing.T) {
	cases := []struct {
		name string
		time string
	}{
		{name: "event time strictly below overall watermark", time: "999"},
		{name: "event time exactly equal to overall watermark", time: "1500"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			record := `{"type":"event","key":"z","time":` + tc.time + `,"value":1,"partition":1}`
			lines := append(idleFieldOrderFixtureLines(), record)
			lines = append(lines, idleFieldOrderDeadSuffix()...)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
			if err == nil {
				t.Fatalf("an event for an idle partition must fail; got nil, stdout=%q", stdout)
			}
			var inputErr *InputError
			if !errors.As(err, &inputErr) {
				t.Fatalf("want *InputError, got %T: %v", err, err)
			}
			if inputErr.Line != 7 {
				t.Errorf("InputError.Line = %d, want 7", inputErr.Line)
			}
			for _, sub := range []string{
				"event for idle partition 1 is not allowed",
				"send a watermark to resume it first",
			} {
				if !strings.Contains(inputErr.Reason, sub) {
					t.Errorf("reason %q must contain %q", inputErr.Reason, sub)
				}
			}
			// The record's fields are legal: no field must be blamed.
			for _, f := range []string{`"key"`, `"time"`, `"value"`, `"partition"`} {
				if strings.Contains(inputErr.Reason, f) {
					t.Errorf("an idle-partition failure must not blame field %s: %q", f, inputErr.Reason)
				}
			}
			if stderr != "" {
				t.Errorf("an idle-partition event is fatal, not a late skip; got late log %q", stderr)
			}
			if stdout != idleFieldOrderWantFirstWindow {
				t.Errorf("the open overlapping window must not be back-filled:\n got: %q\nwant: %q", stdout, idleFieldOrderWantFirstWindow)
			}
		})
	}
}

// TestSlidingIdlePartitionActiveControlLateSkipsAndEqualCounts is the normal
// control using the identical history and physical line 7, but sent to the
// still-active partition 0 rather than idle partition 1:
//
//   - A field-legal event with time 999 < overall watermark 1500 is only
//     recorded as late (one notice naming line 7) and processing continues; it
//     adds nothing to any window even though 999 is inside the open
//     [600,1600).
//   - A field-legal event with time exactly 1500 is not late: it joins the
//     unclosed [600,1600) (1500 is its only containing window), moving count
//     and sum.
//   - Partition 0's watermark reaching 1600 then closes [600,1600) with the
//     two pre-idle events plus the time==1500 event (count 3, sum 2+3+4 = 9);
//     the skipped 999/6 contributes nothing.
//
// No idle error appears because partition 0 never idled, and resume/window
// rules are otherwise unchanged.
func TestSlidingIdlePartitionActiveControlLateSkipsAndEqualCounts(t *testing.T) {
	lines := append(idleFieldOrderFixtureLines(),
		`{"type":"event","key":"k","time":999,"value":6,"partition":0}`,  // line 7: late vs overall 1500
		`{"type":"event","key":"k","time":1500,"value":4,"partition":0}`, // line 8: equal, joins [600,1600)
		`{"type":"watermark","time":1600,"partition":0}`,                 // line 9: closes [600,1600)
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("the active partition's legal events must not fail: %v", err)
	}
	wantNotice := "line 7: late event time=999 below current watermark 1500, skipped\n"
	if stderr != wantNotice {
		t.Fatalf("late notice mismatch:\n got: %q\nwant: %q", stderr, wantNotice)
	}
	if strings.Count(stderr, "skipped\n") != 1 {
		t.Errorf("the late event must be reported exactly once, got %q", stderr)
	}
	if strings.Contains(stderr, "idle") {
		t.Errorf("an active-partition event must not mention idleness: %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		// Pre-idle 700/2 and 1000/3, plus the equal-to-watermark 1500/4; the
		// skipped 999/6 adds nothing: count 3 / sum 9.
		`{"key":"k","start":600,"end":1600,"count":3,"sum":9}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
		{Key: "k", Start: 600, End: 1600, Count: 3, Sum: 9},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// TestSlidingIdlePartitionResumeKeepsWindowClosureCompatible proves the
// existing resume and window-closure rules stay compatible alongside the
// priority guarantee: idle partition 1 resumes with a watermark at least the
// overall watermark (1500, equality resumes), a post-resume event at 1500
// joins the open [600,1600), and the window then closes on the merged minimum
// 1600 with both partitions' contributions (count 3, sum 9). No field error,
// idle error or late notice occurs on the normal path.
func TestSlidingIdlePartitionResumeKeepsWindowClosureCompatible(t *testing.T) {
	lines := append(idleFieldOrderFixtureLines(),
		`{"type":"watermark","time":1500,"partition":1}`,                 // line 7: resume at the overall watermark
		`{"type":"event","key":"k","time":1500,"value":4,"partition":1}`, // line 8: joins [600,1600)
		`{"type":"watermark","time":1600,"partition":0}`,                 // line 9: min stays 1500, closes nothing new
		`{"type":"watermark","time":1600,"partition":1}`,                 // line 10: min = 1600, closes [600,1600)
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	if err != nil {
		t.Fatalf("the resume and merged close sequence must succeed: %v", err)
	}
	if stderr != "" {
		t.Fatalf("the normal resume path must produce no notice, got %q", stderr)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		// Pre-idle 700/2 and 1000/3, plus the resumed partition's 1500/4.
		`{"key":"k","start":600,"end":1600,"count":3,"sum":9}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("window output mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

// runIdleFieldError runs the shared history plus the given line-7 record (the
// dead suffix is unnecessary when only the error is compared) and returns the
// *InputError, failing the test on any other outcome.
func runIdleFieldError(t *testing.T, record string) *InputError {
	t.Helper()
	lines := append(idleFieldOrderFixtureLines(), record)
	_, _, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 2)
	return inputErrorFrom(t, err)
}

package edgefleet

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

// Regression safeguard for partition numbering as a mere source label.
//
// A partition number only identifies which independent input source a record
// came from; it must never enter the aggregate semantics: relabeling every
// partition number with a single bijection -- one that stays inside [0,N),
// neither merges two sources nor drops one, and is applied to EVERY record
// kind that carries a partition (events, watermarks and idle declarations) --
// must leave the window results byte-for-byte identical in content, row count
// and order, must leave every late notice identical in its event time, the
// watermark cited and the physical line number, and must keep a normal run
// successful. The only text allowed to change is the partition number named
// in an input error, which must be the relabeled number on the same physical
// line.
//
// The scenario is one business stream (window 1000, slide 600 -- 600 does not
// divide 1000) merged over THREE sources, one key "k", and the three sources
// play genuinely different roles that land on the zero, the maximum legal and
// a middle number:
//
//   - partition 0 (the zero index) is the source that races ahead;
//   - partition 2 (the maximum legal index for --partitions 3) is the source
//     that pins the overall effective watermark by lagging, then catches up;
//   - partition 1 (a middle index) is the source that goes idle and later
//     resumes with a legal watermark.
//
// The same key's events arrive from all three sources and, because the slide
// interval does not divide the window length, several of them land in more
// than one overlapping window. The stream first closes only the early window
// while the later overlapping window keeps receiving events. Source numbers
// never appear in the output. Everything goes through the public
// RunAggregatePartitionedSliding entry point; no production code, public entry
// point, result format or error convention is changed, and no renumbering
// command is introduced.

// partitionRenumberPermutation is the relabeling under test. It is a
// bijection of {0,1,2} onto itself that moves every role off its original
// number: the fast source 0 -> 2 (now the maximum legal index), the idle
// source 1 -> 0 (now the zero index), the limiter 2 -> 1 (now a middle
// index), so each of zero/max/middle is exercised by a different source than
// before, while the total partition count stays 3.
var partitionRenumberPermutation = map[int64]int64{0: 2, 1: 0, 2: 1}

// renumberFixtureSuccessLines is the shared 17-line stream. Partition numbers
// shown are the ORIGINAL labels; renumberPartitionFields applies the
// bijection. The blank-free layout keeps physical line numbers obvious.
//
//	line 1:  p0 event t=700  v=2 -> [0,1000) and [600,1600)
//	line 2:  p1 event t=1000 v=3 -> [600,1600)
//	line 3:  p2 event t=1300 v=5 -> [600,1600) and [1200,2200)
//	line 4:  p0 watermark 1600       (fast source races ahead)
//	line 5:  p1 watermark 1600
//	line 6:  p2 watermark 600        (laggard pins the effective minimum at 600)
//	line 7:  p2 watermark 1000       (effective advances to 1000: closes only [0,1000))
//	line 8:  p1 declares idle        (excluded from the minimum; effective stays 1000)
//	line 9:  p0 event t=999  v=9     (strictly below effective 1000: late, skipped whole)
//	line 10: p0 event t=1200 v=6     (1200 < p0's OWN watermark 1600, yet accepted:
//	                                  lateness uses the overall effective 1000, not the
//	                                  source's own watermark; joins [600,1600),[1200,2200))
//	line 11: p2 event t=1000 v=4     (equal to effective 1000: still counted; joins [600,1600))
//	line 12: p1 watermark 1600       (legal resume: >= old 1600 and >= effective 1000)
//	line 13: p2 watermark 1600       (effective = min(1600,1600,1600) = 1600: closes [600,1600))
//	line 14: p1 event t=1900 v=7     (resumed source participates again; -> [1200,2200) and [1800,2800))
//	line 15: p0 watermark 2200
//	line 16: p1 watermark 2200
//	line 17: p2 watermark 2200       (effective 2200: closes [1200,2200); [1800,2800) stays open)
func renumberFixtureSuccessLines() []string {
	return []string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
		`{"type":"event","key":"k","time":1300,"value":5,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":1}`,
		`{"type":"watermark","time":600,"partition":2}`,
		`{"type":"watermark","time":1000,"partition":2}`,
		`{"type":"idle","partition":1}`,
		`{"type":"event","key":"k","time":999,"value":9,"partition":0}`,
		`{"type":"event","key":"k","time":1200,"value":6,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":1}`,
		`{"type":"watermark","time":1600,"partition":2}`,
		`{"type":"event","key":"k","time":1900,"value":7,"partition":1}`,
		`{"type":"watermark","time":2200,"partition":0}`,
		`{"type":"watermark","time":2200,"partition":1}`,
		`{"type":"watermark","time":2200,"partition":2}`,
	}
}

// Expected window accounting, independently re-checkable per source from the
// valid (non-late) events. The late t=999 event contributes nowhere.
//
//	[0,1000):   p0 {2}                            -> count 1, sum 2
//	[600,1600): p0 {2,6}=8, p1 {3}=3, p2 {5,4}=9  -> count 5, sum 20
//	[1200,2200): p0 {6}=6, p1 {7}=7, p2 {5}=5     -> count 3, sum 18
var renumberFixtureWantRows = []AggregateResult{
	{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
	{Key: "k", Start: 600, End: 1600, Count: 5, Sum: 20},
	{Key: "k", Start: 1200, End: 2200, Count: 3, Sum: 18},
}

const renumberFixtureWantStdout = `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n" +
	`{"key":"k","start":600,"end":1600,"count":5,"sum":20}` + "\n" +
	`{"key":"k","start":1200,"end":2200,"count":3,"sum":18}` + "\n"

const renumberFixtureWantLate = "line 9: late event time=999 below current watermark 1000, skipped\n"

// acceptedSourceEvents lists every event the stream actually accepts (the
// late t=999 record is excluded), keyed by the ORIGINAL source number, so the
// expected per-window counts and sums can be recomputed from each source's
// valid events independently of the watermark/idle machinery and
// independently of the labels the run used.
var acceptedSourceEvents = []struct {
	source int64
	time   int64
	value  int64
}{
	{0, 700, 2},
	{1, 1000, 3},
	{2, 1300, 5},
	{0, 1200, 6},
	{2, 1000, 4},
	{1, 1900, 7},
}

// renumberWindowStarts are the windows closed by the final effective
// watermark 2200, enumerated directly (length 1000, left-closed right-open).
// [1800,2800) is intentionally absent: it stays open at end of input and must
// never be flushed.
var renumberWindowStarts = []int64{0, 600, 1200}

const renumberWindowLength int64 = 1000

// recomputeRowsBySource rebuilds the merged window rows from
// acceptedSourceEvents using plain interval containment (a different
// formulation than the engine's slide arithmetic), and additionally reports
// each source's own count/sum contribution per window start so the merged
// totals can be checked source by source.
func recomputeRowsBySource(t *testing.T) (map[int64]AggregateResult, map[int64]map[int64]struct{ count, sum int64 }) {
	t.Helper()
	rows := make(map[int64]AggregateResult)
	perSource := make(map[int64]map[int64]struct{ count, sum int64 })
	for _, start := range renumberWindowStarts {
		rows[start] = AggregateResult{Key: "k", Start: start, End: start + renumberWindowLength}
		perSource[start] = make(map[int64]struct{ count, sum int64 })
	}
	for _, ev := range acceptedSourceEvents {
		for _, start := range renumberWindowStarts {
			if ev.time >= start && ev.time < start+renumberWindowLength {
				r := rows[start]
				r.Count++
				r.Sum += ev.value
				rows[start] = r
				c := perSource[start][ev.source]
				c.count++
				c.sum += ev.value
				perSource[start][ev.source] = c
			}
		}
	}
	return rows, perSource
}

// TestSlidingPartitionRenumberingInvariantSuccess is the core guarantee:
// running the same business stream under the original labels and under the
// relabeling bijection produces exactly the same window output (content, row
// count and order) and the same late notices (event time, watermark and
// physical line number), and both runs succeed. The relabeling touches
// events, watermarks and idle declarations alike and never merges sources or
// leaves a record kind behind.
func TestSlidingPartitionRenumberingInvariantSuccess(t *testing.T) {
	original := renumberFixtureSuccessLines()
	relabeled := renumberPartitionFields(t, original, partitionRenumberPermutation)
	// Guard the guard: the relabeling really is a same-cardinality bijection
	// and really rewrote every partition-bearing record of every kind.
	assertPermutation(t, partitionRenumberPermutation, 3)
	assertEveryPartitionFieldMapped(t, original, relabeled, partitionRenumberPermutation)

	controlOut, controlLate, controlErr := runPartitionedSliding(t, strings.Join(original, "\n")+"\n", 1000, 600, 3)
	movedOut, movedLate, movedErr := runPartitionedSliding(t, strings.Join(relabeled, "\n")+"\n", 1000, 600, 3)

	if controlErr != nil {
		t.Fatalf("the control run must succeed: %v", controlErr)
	}
	if movedErr != nil {
		t.Fatalf("the relabeled run must succeed: %v", movedErr)
	}
	if controlOut != renumberFixtureWantStdout {
		t.Fatalf("control stdout mismatch:\n got: %q\nwant: %q", controlOut, renumberFixtureWantStdout)
	}
	if movedOut != controlOut {
		t.Fatalf("renumbering changed the window results:\n original: %q\nrelabeled: %q", controlOut, movedOut)
	}
	if controlLate != renumberFixtureWantLate {
		t.Fatalf("control late notice mismatch:\n got: %q\nwant: %q", controlLate, renumberFixtureWantLate)
	}
	if movedLate != controlLate {
		t.Fatalf("renumbering changed the late notice (event time/watermark/physical line must stay put):\n original: %q\nrelabeled: %q", controlLate, movedLate)
	}
	if strings.Contains(movedOut, "partition") {
		t.Errorf("the source number must never enter the output: %q", movedOut)
	}

	got := decodeAggregateResults(t, movedOut)
	if len(got) != len(renumberFixtureWantRows) {
		t.Fatalf("row count = %d, want %d", len(got), len(renumberFixtureWantRows))
	}
	for i := range renumberFixtureWantRows {
		if got[i] != renumberFixtureWantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], renumberFixtureWantRows[i])
		}
	}

	// Independently recompute every closed window from each source's valid
	// events; the merged rows and the per-source split must both reconcile.
	rows, perSource := recomputeRowsBySource(t)
	for _, start := range renumberWindowStarts {
		want := rows[start]
		var gotRow *AggregateResult
		for i := range got {
			if got[i].Start == start {
				gotRow = &got[i]
			}
		}
		if gotRow == nil {
			t.Errorf("window starting %d was not emitted", start)
			continue
		}
		if *gotRow != want {
			t.Errorf("window [%d,%d) = %+v, want %+v from per-source events", start, want.End, gotRow, want)
		}
		var sCount, sSum int64
		for _, c := range perSource[start] {
			sCount += c.count
			sSum += c.sum
		}
		if sCount != want.Count || sSum != want.Sum {
			t.Errorf("per-source contributions to [%d,%d) sum to count %d/sum %d, want %d/%d", start, want.End, sCount, sSum, want.Count, want.Sum)
		}
	}
	// The overlapping windows (slide 600 does not divide length 1000) are
	// where the same key's events from all three sources actually merge; the
	// early [0,1000) window legitimately holds only the fast source's event.
	for _, start := range []int64{600, 1200} {
		if len(perSource[start]) != 3 {
			t.Errorf("overlapping window starting %d should merge the same key's events from all 3 sources, got %d", start, len(perSource[start]))
		}
	}
}

// TestSlidingPartitionRenumberingResumeFailureBelowOwnOldWatermark keeps the
// branch where a sleeping source's resume watermark is below its OWN previous
// watermark. The failure must remain an *InputError on the same physical line
// (line 12) naming the actually violated bound ("previous watermark 1600"),
// while the number named for the source follows the relabeling (partition 1
// -> partition 0). Output already produced before the failure stays exactly
// as it was, and records after the failing line produce neither results nor
// late notices -- under either labeling.
func TestSlidingPartitionRenumberingResumeFailureBelowOwnOldWatermark(t *testing.T) {
	lines := renumberFixtureSuccessLines()[:11]
	lines = append(lines,
		`{"type":"watermark","time":900,"partition":1}`, // line 12: 900 < the source's own old 1600
		// Dead suffix: must never run after the fatal line 12.
		`{"type":"event","key":"k","time":998,"value":11,"partition":0}`, // line 13: would be late if reached
		`{"type":"watermark","time":1600,"partition":1}`,                 // line 14
		`{"type":"watermark","time":2200,"partition":0}`,                 // line 15
		`{"type":"watermark","time":2200,"partition":2}`,                 // line 16
	)
	cases := []struct {
		name       string
		recs       []string
		wantSource string
	}{
		{name: "original labels", recs: lines, wantSource: "partition 1"},
		{name: "relabeled 1->0", recs: renumberPartitionFields(t, lines, partitionRenumberPermutation), wantSource: "partition 0"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out, late, err := runPartitionedSliding(t, strings.Join(tc.recs, "\n")+"\n", 1000, 600, 3)
			ie := inputErrorFrom(t, err)
			if ie.Line != 12 {
				t.Errorf("InputError.Line = %d, want 12 (same physical line under relabeling)", ie.Line)
			}
			for _, sub := range []string{
				"resume watermark 900",
				tc.wantSource,
				"previous watermark 1600",
			} {
				if !strings.Contains(ie.Reason, sub) {
					t.Errorf("reason %q must contain %q", ie.Reason, sub)
				}
			}
			if strings.Contains(ie.Reason, "effective watermark") {
				t.Errorf("the violated limit is the source's own previous watermark, not the effective one: %q", ie.Reason)
			}
			// Pre-failure output and the line-9 late notice stay; the dead
			// suffix adds neither a window row nor another notice.
			wantOut := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
			if out != wantOut {
				t.Errorf("stdout mismatch:\n got: %q\nwant: %q", out, wantOut)
			}
			if late != renumberFixtureWantLate {
				t.Errorf("late notices mismatch:\n got: %q\nwant: %q", late, renumberFixtureWantLate)
			}
		})
	}
}

// TestSlidingPartitionRenumberingResumeFailureBelowEffectiveWatermark keeps
// the other failure cause: a source that goes idle BEFORE ever reporting a
// watermark has no previous watermark of its own, so a resume watermark below
// the current OVERALL effective watermark is rejected citing that overall
// bound -- resume legality is never decided from one source's own watermark.
// The error again stays on the same physical line and names the relabeled
// source number.
func TestSlidingPartitionRenumberingResumeFailureBelowEffectiveWatermark(t *testing.T) {
	lines := []string{
		`{"type":"event","key":"k","time":100,"value":1,"partition":0}`, // line 1
		`{"type":"event","key":"k","time":200,"value":2,"partition":2}`, // line 2
		`{"type":"watermark","time":1000,"partition":0}`,                // line 3
		`{"type":"watermark","time":1000,"partition":2}`,                // line 4
		`{"type":"idle","partition":1}`,                                 // line 5: never-reported source idles
		`{"type":"watermark","time":2000,"partition":0}`,                // line 6
		`{"type":"watermark","time":2000,"partition":2}`,                // line 7: overall effective = 2000
		`{"type":"watermark","time":1500,"partition":1}`,                // line 8: 1500 < overall 2000
		// Dead suffix.
		`{"type":"event","key":"k","time":1900,"value":8,"partition":1}`, // line 9
		`{"type":"watermark","time":2000,"partition":1}`,                 // line 10
	}
	cases := []struct {
		name       string
		recs       []string
		wantSource string
	}{
		{name: "original labels", recs: lines, wantSource: "partition 1"},
		{name: "relabeled 1->0", recs: renumberPartitionFields(t, lines, partitionRenumberPermutation), wantSource: "partition 0"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out, late, err := runPartitionedSliding(t, strings.Join(tc.recs, "\n")+"\n", 1000, 600, 3)
			ie := inputErrorFrom(t, err)
			if ie.Line != 8 {
				t.Errorf("InputError.Line = %d, want 8 (same physical line under relabeling)", ie.Line)
			}
			for _, sub := range []string{
				"resume watermark 1500",
				tc.wantSource,
				"current effective watermark 2000",
			} {
				if !strings.Contains(ie.Reason, sub) {
					t.Errorf("reason %q must contain %q", ie.Reason, sub)
				}
			}
			if strings.Contains(ie.Reason, "previous watermark") {
				t.Errorf("a never-reported source has no previous watermark to cite: %q", ie.Reason)
			}
			wantOut := `{"key":"k","start":0,"end":1000,"count":2,"sum":3}` + "\n"
			if out != wantOut {
				t.Errorf("stdout mismatch:\n got: %q\nwant: %q", out, wantOut)
			}
			if late != "" {
				t.Errorf("a rejected resume produces no late notice, got %q", late)
			}
		})
	}
}

// TestSlidingPartitionRenumberingPermutationIsABijection pins the labeling
// constraint itself: the relabeling must be a one-to-one correspondence onto
// {0,1,2}, stay in range and keep using the zero and the maximum legal index,
// so sources can never be merged or dropped.
func TestSlidingPartitionRenumberingPermutationIsABijection(t *testing.T) {
	if !isPermutation(partitionRenumberPermutation, 3) {
		t.Fatalf("the renumbering under test must be a bijection: %v", partitionRenumberPermutation)
	}
	// Maps that merge sources, drop a source, leave the range or keep a
	// boundary role fixed must all be rejected by the same predicate.
	for name, bad := range map[string]map[int64]int64{
		"two sources merge into one": {0: 0, 1: 0, 2: 1},
		"a source is dropped":        {0: 2, 1: 0},
		"target out of range":        {0: 2, 1: 3, 2: 1},
		"zero role never moves":      {0: 0, 1: 2, 2: 1},
		"max role never moves":       {0: 1, 1: 0, 2: 2},
	} {
		if isPermutation(bad, 3) {
			t.Errorf("%s must not be accepted as a renumbering bijection: %v", name, bad)
		}
	}
}

// isPermutation reports whether m is a bijection of {0,...,n-1} onto itself:
// every source is covered and maps to a distinct in-range target, the zero and
// maximum legal indices are both reused, and neither boundary role keeps its
// original number (so the safeguard genuinely moves the boundary roles).
func isPermutation(m map[int64]int64, n int64) bool {
	if int64(len(m)) != n {
		return false
	}
	seen := make(map[int64]bool)
	for old, next := range m {
		if old < 0 || old >= n || next < 0 || next >= n {
			return false
		}
		if seen[next] {
			return false
		}
		seen[next] = true
	}
	if !seen[0] || !seen[n-1] {
		return false
	}
	if m[0] == 0 || m[n-1] == n-1 {
		return false
	}
	return true
}

// assertPermutation fails the test unless m is a renumbering bijection.
func assertPermutation(t *testing.T, m map[int64]int64, n int64) {
	t.Helper()
	if !isPermutation(m, n) {
		t.Fatalf("renumbering %v is not a bijection of [0,%d) onto itself", m, n)
	}
}

// assertEveryPartitionFieldMapped compares two physical input streams that
// differ only in partition labels: every record keeps its type and line
// position, and each partition-bearing record (event, watermark and idle
// alike) carries exactly f(original). This proves no record kind was missed
// and no source was merged or relabeled inconsistently.
func assertEveryPartitionFieldMapped(t *testing.T, original, relabeled []string, f map[int64]int64) {
	t.Helper()
	if len(original) != len(relabeled) {
		t.Fatalf("renumbering changed the record count: %d -> %d", len(original), len(relabeled))
	}
	kinds := map[string]int{}
	for i, before := range original {
		var o, rl map[string]json.RawMessage
		if err := json.Unmarshal([]byte(before), &o); err != nil {
			t.Fatalf("original line %d is not JSON: %v", i+1, err)
		}
		if err := json.Unmarshal([]byte(relabeled[i]), &rl); err != nil {
			t.Fatalf("relabeled line %d is not JSON: %v", i+1, err)
		}
		if string(o["type"]) != string(rl["type"]) {
			t.Errorf("line %d record type changed: %s -> %s", i+1, o["type"], rl["type"])
		}
		raw, ok := o["partition"]
		if !ok {
			t.Errorf("line %d (%s) carries no partition field to relabel", i+1, o["type"])
			continue
		}
		var oldP int64
		if err := json.Unmarshal(raw, &oldP); err != nil {
			t.Fatalf("line %d partition is not an integer: %v", i+1, err)
		}
		var newP int64
		if err := json.Unmarshal(rl["partition"], &newP); err != nil {
			t.Fatalf("line %d relabeled partition is not an integer: %v", i+1, err)
		}
		if newP != f[oldP] {
			t.Errorf("line %d (%s): partition %d relabeled to %d, want %d", i+1, o["type"], oldP, newP, f[oldP])
		}
		kinds[string(o["type"])]++
	}
	for _, kind := range []string{`"event"`, `"watermark"`, `"idle"`} {
		if kinds[kind] == 0 {
			t.Errorf("the stream must include %s records so that kind cannot be skipped by renumbering", kind)
		}
	}
}

// renumberPartitionFields returns the physical records with every record's
// partition field replaced by f(its old value). It rewrites events,
// watermarks and idle declarations with the single correspondence and leaves
// record order and all other fields untouched. Re-marshaling changes only
// formatting, never decoded content, so the engine sees an identical stream
// apart from source labels.
func renumberPartitionFields(t *testing.T, records []string, f map[int64]int64) []string {
	t.Helper()
	out := make([]string, len(records))
	for i, line := range records {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal([]byte(line), &obj); err != nil {
			t.Fatalf("line %d is not JSON: %v", i+1, err)
		}
		raw, ok := obj["partition"]
		if !ok {
			t.Fatalf("line %d has no partition field to renumber: %s", i+1, line)
		}
		var p int64
		if err := json.Unmarshal(raw, &p); err != nil {
			t.Fatalf("line %d partition is not an integer: %v", i+1, err)
		}
		next, ok := f[p]
		if !ok {
			t.Fatalf("line %d: no renumbering target for source %d", i+1, p)
		}
		obj["partition"] = json.RawMessage(fmt.Sprintf("%d", next))
		b, err := json.Marshal(obj)
		if err != nil {
			t.Fatalf("line %d could not be re-marshaled: %v", i+1, err)
		}
		out[i] = string(b)
	}
	return out
}

